def compute(vars):
    prior = vars["v1"]
    current = vars["v2"]

    if prior == 0:
        return None

    change = current - prior
    percentage_change = (change / prior) * 100

    return {
        "value": percentage_change,
        "trace": {
            "prior_value": prior,
            "current_value": current,
            "absolute_change": change,
            "percentage_change": percentage_change,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
